const postalButton=document.querySelector(".postal-button"),formAddr=document.querySelector(".p-form__address");postalButton&&postalButton.addEventListener("click",function(){AjaxZip3.zip2addr("郵便番号","","現住所","現住所"),AjaxZip3.onSuccess=function(){formAddr.classList.remove("failure")},AjaxZip3.onFailure=function(){formAddr.classList.add("failure")}});const formFiles=document.querySelectorAll(".p-form__file input"),formFilesArr=Array.prototype.slice.call(formFiles);function toSlash(t){if(new RegExp(/^[0-9]{8}$/).test(t.value)){let e=t.value.trim(),o=e.substr(0,4),l=e.substr(4,2),s=e.substr(6,2);t.value=o+"年"+l+"月"+s+"日"}}function offSlash(t){let e=new RegExp("/","g"),o=t.value.replace(e,"");isNaN(o)||(t.value=o,t.select())}function toSlash02(t){if(new RegExp(/^[0-9]{6}$/).test(t.value)){let e=t.value.trim(),o=e.substr(0,4),l=e.substr(4,2);t.value=o+"年"+l+"月"}}function offSlash02(t){let e=new RegExp("/","g"),o=t.value.replace(e,"");isNaN(o)||(t.value=o,t.select())}function toPostFmt(t){if(7==t.value.trim().length&&!isNaN(t.value)){let e=t.value.trim(),o=e.substr(0,3),l=e.substr(3);t.value=o+"-"+l}}function offPostFmt(t){let e=new RegExp("-","g"),o=t.value.replace(e,"");isNaN(o)||(t.value=o,t.select())}formFilesArr&&formFilesArr.map(t=>{t.addEventListener("change",e=>{t.parentNode.querySelector("span").textContent=e.target.files[0].name})}),window.addEventListener("load",function(){let t=document.getElementsByClassName("ymd");for(let e=0;e<t.length;e++)t[e].onfocus=function(){offSlash(this)},t[e].onblur=function(){toSlash(this)};let e=document.getElementsByClassName("ym");for(let t=0;t<e.length;t++)e[t].onfocus=function(){offSlash02(this)},e[t].onblur=function(){toSlash02(this)};let o=document.getElementsByClassName("postcd");for(let t=0;t<o.length;t++)o[t].onfocus=function(){offPostFmt(this)},o[t].onblur=function(){toPostFmt(this)}});